import{_ as t,o as s,c as n,aN as r}from"./chunks/framework.D31DlcCL.js";const o="/img/math-enumeration-logic.svg",d=JSON.parse('{"title":"奥数基础：枚举法，把所有可能“一网打尽”","description":"面对“有多少种可能”的问题，最好的办法就是把它们一个一个列出来。本文教你如何运用枚举法，通过分类和有序排列，做到不重复、不遗漏地解决计数难题。","frontmatter":{"title":"奥数基础：枚举法，把所有可能“一网打尽”","date":"2026-02-19T09:00:00.000Z","categories":["数学"],"tags":["小学奥数","枚举法","分类讨论","组合计数"],"description":"面对“有多少种可能”的问题，最好的办法就是把它们一个一个列出来。本文教你如何运用枚举法，通过分类和有序排列，做到不重复、不遗漏地解决计数难题。","cover":"/img/math-enumeration-logic.svg","top_img":"/img/banner.svg","toc_number":true},"headers":[],"relativePath":"posts/primary-math-olympiad-enumeration.md","filePath":"posts/primary-math-olympiad-enumeration.md","lastUpdated":null}'),e={name:"posts/primary-math-olympiad-enumeration.md"};function l(i,a,m,p,h,g){return s(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="奥数基础-枚举法-把所有可能-一网打尽" tabindex="-1">奥数基础：枚举法，把所有可能“一网打尽” <a class="header-anchor" href="#奥数基础-枚举法-把所有可能-一网打尽" aria-label="Permalink to &quot;奥数基础：枚举法，把所有可能“一网打尽”&quot;">​</a></h1><p>在奥数题里，我们经常会遇到这样的提问：“一共有多少种不同的走法？”或者“能组成多少个不同的两位数？”</p><p>这种要求算出所有可能情况数量的问题，最基础也最可靠的方法就是**“枚举法”**。简单来说，枚举法就是把符合条件的答案一个一个列举出来。</p><hr><h2 id="一、-核心法宝-有序与分类" tabindex="-1">一、 核心法宝：有序与分类 <a class="header-anchor" href="#一、-核心法宝-有序与分类" aria-label="Permalink to &quot;一、 核心法宝：有序与分类&quot;">​</a></h2><p>枚举法最怕两个词：<strong>重复</strong> 和 <strong>遗漏</strong>。为了躲开这两个陷阱，我们必须遵守两个原则：</p><p><img src="'+o+'" alt="枚举法逻辑示意图"></p><ol><li><strong>有序性</strong>：从小到大，或者从大到小，按一定的顺序列举。</li><li><strong>分类性</strong>：把复杂的问题拆成几个简单的小类，分别数清楚。</li></ol><hr><h2 id="二、-实战模型解析" tabindex="-1">二、 实战模型解析 <a class="header-anchor" href="#二、-实战模型解析" aria-label="Permalink to &quot;二、 实战模型解析&quot;">​</a></h2><h3 id="模型-1-数字组合" tabindex="-1">模型 1：数字组合 <a class="header-anchor" href="#模型-1-数字组合" aria-label="Permalink to &quot;模型 1：数字组合&quot;">​</a></h3><p><strong>【例题 1】</strong>：用 1, 2, 3 这三个数字，可以组成多少个没有重复数字的两位数？ <strong>解析</strong>： 我们按“十位数字”分类：</p><ul><li>十位是 1：12, 13（2个）</li><li>十位是 2：21, 23（2个）</li><li>十位是 3：31, 32（2个） <strong>计算</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>+</mo><mn>2</mn><mo>+</mo><mn>2</mn><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">2 + 2 + 2 = 6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>（个）。 <strong>答案</strong>：6 个。</li></ul><h3 id="模型-2-付钱问题" tabindex="-1">模型 2：付钱问题 <a class="header-anchor" href="#模型-2-付钱问题" aria-label="Permalink to &quot;模型 2：付钱问题&quot;">​</a></h3><p><strong>【例题 2】</strong>：买一个 5 角钱的练习本，可以怎样付钱？（只有 1 角和 2 角的硬币） <strong>解析</strong>： 我们按“2角硬币的个数”分类：</p><ul><li>2角有 0 个：5个1角（1种）</li><li>2角有 1 个：1个2角 + 3个1角（1种）</li><li>2角有 2 个：2个2角 + 1个1角（1种） <strong>答案</strong>：共 3 种付钱方法。</li></ul><hr><h2 id="三、-进阶技巧-树状图法" tabindex="-1">三、 进阶技巧：树状图法 <a class="header-anchor" href="#三、-进阶技巧-树状图法" aria-label="Permalink to &quot;三、 进阶技巧：树状图法&quot;">​</a></h2><p>当情况比较复杂时，可以画出像树枝一样的图（如封面图所示）。</p><ul><li><strong>树干</strong>：第一步的选择。</li><li><strong>树枝</strong>：第二步的选择。</li><li><strong>叶子</strong>：最终的结果。</li></ul><hr><h2 id="四、-避坑指南-看清限制条件" tabindex="-1">四、 避坑指南：看清限制条件 <a class="header-anchor" href="#四、-避坑指南-看清限制条件" aria-label="Permalink to &quot;四、 避坑指南：看清限制条件&quot;">​</a></h2><ul><li><strong>警示</strong>：题目有没有说“数字不能重复”？有没有说“钱必须正好”？</li><li><strong>细节</strong>：在数字组合题中，<strong>0 不能放在最高位</strong>，这是最容易漏掉的限制！</li></ul><hr><h2 id="五、-练一练-全能计数官" tabindex="-1">五、 练一练（全能计数官） <a class="header-anchor" href="#五、-练一练-全能计数官" aria-label="Permalink to &quot;五、 练一练（全能计数官）&quot;">​</a></h2><ol><li><strong>数字关</strong>：用 0, 4, 5 三个数字，可以组成多少个不同的两位数？</li><li><strong>路线关</strong>：从 A 地到 B 地有 2 条路，从 B 地到 C 地有 3 条路。从 A 地经过 B 地到 C 地，一共有多少种走法？</li><li><strong>搭配关</strong>：小明有 2 件上衣和 3 条裤子，一共有多少种不同的穿法？</li></ol><hr><p><em>总结：枚举法是数学中的“笨功夫”，但也是最扎实的功夫。只要你心中有顺序，所有的可能都逃不出你的手掌心！</em></p>',28)])])}const u=t(e,[["render",l]]);export{d as __pageData,u as default};
